local function clamp(x,a,b)return math.max(a,math.min(b,x))end
local function sign(x)return x<0 and -1 or 1 end
local function color(i)local c=palette[cfg.palette][i];g.setColor(math.floor(c/65536)%256/255,math.floor(c/256)%256/255,c%256/255)end
local function box(x,y,w,h,i)color(i);g.rectangle("fill",math.floor(x),math.floor(y),w,h)end
local function sprite(n,x,y,flip,tint)local a=sprites[n];for j,row in ipairs(a)do for i=1,#row do local v=tonumber(row:sub(i,i));if v then box(x+(flip and #row-i or i-1),y+j-1,1,1,v==1 and tint or v)end end end end
local function delta(x,y)local d=x-y;if cfg.wrap then d=(d+96)%192-96 end;return d end
local function save()local a={}for _,r in ipairs(rules)do a[#a+1]=r[2].."="..tostring(cfg[r[2]])end;love.filesystem.write("settings.txt",table.concat(a,"\n"))end
local function load()local s=love.filesystem.read("settings.txt")or "";for k,v in s:gmatch("(%w+)=([^\n]+)")do for _,r in ipairs(rules)do if r[2]==k then if type(cfg[k])=="boolean" then cfg[k]=v=="true" else cfg[k]=clamp(tonumber(v)or cfg[k],r[3],r[4])end end end end end
local function equip(w)p.weapon=w;p.ammo=cap[w];p.cd=0 end
local function spawn(t,i)local l=platforms[i+1];t.x=l[1]+l[3]/2-4;t.y=l[2]-8;t.v=i%2==0 and -.42 or .42;t.knock=0;t.hp=3;t.wait=0;t.flash=0 end
local function newcrate()local l=platforms[love.math.random(2,#platforms)];crate={x=l[1]+love.math.random(2,l[3]-7),y=l[2]-6,wait=0}end
local function reset()p={x=90,y=88,vx=0,vy=0,ground=true,jumps=0,dir=1,dash=0,attack=0};equip(1);targets={};for i=1,6 do local t={};spawn(t,i);targets[i]=t end;shots={};parts={};score=0;tick=0;sh=0;newcrate();prev={}end
local function burst(x,y)for i=1,12 do parts[#parts+1]={x=x,y=y,vx=love.math.random()*3.4-1.7,vy=love.math.random()*2.5-2,life=18}end;if cfg.shake then sh=5 end end
local function hit(t,d,dir)t.hp=t.hp-d;t.knock=dir*2.3;t.flash=6;burst(t.x+4,t.y+4);if t.hp<=0 then t.wait=100;score=score+1 end end
local function explode(x,y)burst(x,y);if cfg.targets then for i=1,cfg.count do local t=targets[i];if t.hp>0 and delta(t.x+4,x)^2+(t.y+4-y)^2<361 then hit(t,3,sign(delta(t.x,x)))end end end end
local function fire()local w=p.weapon;if p.cd>0 or(cfg.ammo and p.ammo==0)then return end;p.cd=cooldown[w];p.attack=math.min(16,p.cd);if cfg.ammo and p.ammo>0 then p.ammo=p.ammo-1 end;local x,y=p.x+4+p.dir*6,p.y+6
if w==1 or w==3 or w==8 then local reach=w==8 and 22 or w==3 and 15 or 17;if cfg.targets then for i=1,cfg.count do local t=targets[i];local d=p.dir*delta(t.x+4,x);if t.hp>0 and math.abs(t.y+4-y)<12 and d>=-5 and d<reach then hit(t,damage[w],p.dir)end end end;burst(x+p.dir*4,y)
else local n=w==4 and 5 or 1;local speed=({0,4.5,0,3.8,3.2,2.8,2.2})[w];for i=1,n do shots[#shots+1]={x=x,y=y,vx=p.dir*speed,vy=(i-(n+1)/2)*.32,w=w,life=100,b=3}end;if w==4 or w==7 then p.vx=p.vx-p.dir*1.1 end end end
local buttons={{"L","left"},{"R","right"},{"C","cycle"},{"V","refill"},{"X","dash"},{"Z","attack"},{"J","jump"}}
local function controls()local a={};local k=love.keyboard.isDown;a.left=k("left","a");a.right=k("right","d");a.jump=k("up","w","space");a.dash=k("x");a.attack=k("z");a.cycle=k("c");a.refill=k("v");for _,v in pairs(touches)do a[v]=true end;local j=love.joystick.getJoysticks()[1];if j and j:isGamepad()then a.left=a.left or j:isGamepadDown("dpleft")or j:getGamepadAxis("leftx")<-.3;a.right=a.right or j:isGamepadDown("dpright")or j:getGamepadAxis("leftx")>.3;a.jump=a.jump or j:isGamepadDown("a");a.attack=a.attack or j:isGamepadDown("b");a.dash=a.dash or j:isGamepadDown("leftshoulder");a.cycle=a.cycle or j:isGamepadDown("y");a.refill=a.refill or j:isGamepadDown("x")end;return a end
local function step()tick=tick+1;local a=controls();if p.cd>0 then p.cd=p.cd-1 end;if a.left~=a.right then p.dir=a.left and -1 or 1;p.vx=p.vx+p.dir*.22 else p.vx=p.vx*.78 end;p.vx=clamp(p.vx,-1.45*cfg.speed/100,1.45*cfg.speed/100);if a.jump and not prev.jump and(p.ground or cfg.double and p.jumps<2)then p.vy=-3.5;p.jumps=p.ground and 1 or 2;p.ground=false end;if a.dash and not prev.dash then p.dash=9 end;if a.cycle and not prev.cycle then equip(p.weapon%8+1)end;if a.refill and not prev.refill then p.ammo=cap[p.weapon]end;if a.attack and not prev.attack then fire()end;prev=a;if p.dash>0 then p.vx=p.dir*3.5;p.vy=0;p.dash=p.dash-1 else p.vy=math.min(p.vy+.16*cfg.gravity/100,3.8)end;p.attack=math.max(0,p.attack-1);local old=p.y;p.x=p.x+p.vx;if cfg.wrap then if p.x>192 then p.x=-8 elseif p.x< -8 then p.x=192 end else p.x=clamp(p.x,0,184)end;p.y=p.y+p.vy;p.ground=false;for _,l in ipairs(platforms)do if p.vy>=0 and old+12<=l[2]+.01 and p.y+12>=l[2] and p.x+7>l[1] and p.x<l[1]+l[3]then p.y=l[2]-12;p.vy=0;p.ground=true;p.jumps=0;break end end;if p.y>120 then p.x=90;p.y=88;p.vx=0;p.vy=0 end
if cfg.crates then if crate.wait>0 then crate.wait=crate.wait-1;if crate.wait==0 then newcrate()end elseif math.abs(delta(p.x+4,crate.x+3))<7 and math.abs(p.y+3-crate.y)<9 then equip((p.weapon+love.math.random(1,7)-1)%8+1);crate.wait=cfg.delay*60;burst(crate.x+3,crate.y+3)end end
if cfg.targets then for i=1,cfg.count do local t=targets[i];if t.hp<=0 then t.wait=t.wait-1;if t.wait<=0 then spawn(t,i)end else local l=platforms[i+1];t.flash=math.max(0,t.flash-1);t.x=t.x+t.v+t.knock;t.knock=t.knock*.8;if t.x<l[1]or t.x>l[1]+l[3]-8 then t.x=clamp(t.x,l[1],l[1]+l[3]-8);t.v=-t.v end end end end
for i=#shots,1,-1 do local s=shots[i];local oldy=s.y;s.x=s.x+s.vx;s.y=s.y+s.vy;s.life=s.life-1;if s.w==5 then s.vy=s.vy+.035 end;local dead=s.life<=0 or s.y<0 or s.y>108;if cfg.wrap then s.x=s.x%192 elseif s.x<0 or s.x>=192 then if s.w==6 and s.b>0 then s.b=s.b-1;s.vx=-s.vx;s.x=clamp(s.x,0,191)else dead=true end end;for _,l in ipairs(platforms)do if s.x>=l[1]and s.x<l[1]+l[3]and((oldy<l[2]and s.y>=l[2])or(oldy>l[2]+4 and s.y<=l[2]+4))then if s.w==6 and s.b>0 then s.b=s.b-1;s.vy=-s.vy;s.y=oldy else dead=true end;break end end;if not dead and cfg.targets then for j=1,cfg.count do local t=targets[j];if t.hp>0 and math.abs(delta(t.x+4,s.x))<5 and math.abs(t.y+4-s.y)<5 then if s.w~=7 then hit(t,damage[s.w],sign(s.vx))end;dead=true;break end end end;if dead then if s.w==7 then explode(s.x,s.y)end;table.remove(shots,i)end end
for i=#parts,1,-1 do local q=parts[i];q.x=q.x+q.vx;q.y=q.y+q.vy;q.vy=q.vy+.12;q.life=q.life-1;if q.life<=0 then table.remove(parts,i)end end;sh=math.max(0,sh-1)end
local function change(i,d)local r=rules[i];if not r then return end;local k=r[2];if type(cfg[k])=="boolean"then cfg[k]=not cfg[k]else cfg[k]=clamp(cfg[k]+d*r[5],r[3],r[4])end;save()end
local function layout()local w,h=g.getDimensions();local area=touchMode and h*.78 or h;scale=math.min(w/W,area/H);if scale>=1 then scale=math.floor(scale)end;ox=(w-W*scale)/2;oy=(area-H*scale)/2 end
local function uiButton(i)local w,h=g.getDimensions();local bw=math.min(w/8,h*.19);local x=(i-1)*w/7+(w/7-bw)/2;return x,h-bw-4,bw,bw end
local function touchAction(x,y)for i,b in ipairs(buttons)do local a,c,w,h=uiButton(i);if x>=a and x<a+w and y>=c and y<c+h then return b[2]end end end
local function tap(x,y)local xx,yy=(x-ox)/scale,(y-oy)/scale;if mode=="settings"then if yy>=91 then if xx<95 then mode="arena";prev=controls()else reset();mode="arena"end;return end;local col=xx>=96 and 1 or 0;local row=math.floor((yy-16)/12);local i=col*6+row+1;if row>=0 and row<6 and xx>=0 and xx<192 then menuIndex=i;change(i,xx%96<48 and -1 or 1)end elseif xx>=153 and yy>=0 and yy<13 then mode="settings";touches={}end end
function love.load()g.setDefaultFilter("nearest","nearest");canvas=g.newCanvas(W,H);font=g.newFont(8);uiFont=g.newFont(18);touchMode=love.system.getOS()=="Android"or love.system.getOS()=="iOS";load();reset();mode="arena";acc=0;layout()end
function love.update(dt)layout();if mode~="arena"then acc=0;return end;acc=acc+math.min(dt,.1);while acc>=1/60 do step();acc=acc-1/60 end end
function love.draw()g.setCanvas(canvas);g.clear(.075,.09,.115,1);g.setFont(font)
if mode=="settings"then color(2);g.print("RICOCHET / SETTINGS",4,1);for i,r in ipairs(rules)do local x=4+math.floor((i-1)/6)*96;local y=16+(i-1)%6*12;box(x,y,88,11,i==menuIndex and 4 or 3);local v=cfg[r[2]];if r[2]=="palette"then v=names[v]elseif type(v)=="boolean"then v=v and "ON"or "OFF"end;color(2);g.print(r[1].." "..v,x+2,y+1)end;color(5);g.print("< BACK",4,95);g.print("RESTART >",126,95)
else for x=12,191,32 do box(x,12,4,88,3)end;for _,l in ipairs(platforms)do for x=l[1],l[1]+l[3]-1,8 do sprite("tile",x,l[2],false,1)end end;if cfg.crates and crate.wait==0 then sprite("crate",crate.x,crate.y,false,1)end;if cfg.targets then for i=1,cfg.count do local t=targets[i];if t.hp>0 then sprite(tick%20<10 and "crawler"or"crawler2",t.x,t.y,t.v<0,t.flash>0 and 2 or 6);box(t.x,t.y-2,t.hp*2,1,5)end end end;local pose=p.dash>0 and"dash"or p.attack>0 and"attack"or not p.ground and(p.vy<0 and"jump"or"fall")or math.abs(p.vx)>.15 and(tick%10<5 and"run1"or"run2")or"idle";sprite(pose,p.x,p.y,p.dir<0,1);local w=weapons[p.weapon];sprite(w,p.dir<0 and p.x+3-#sprites[w][1]+1 or p.x+4,p.y+6-math.floor(#sprites[w]/2),p.dir<0,1);for _,s in ipairs(shots)do box(s.x,s.y,s.w==7 and 4 or s.w==5 and 3 or 2,s.w==6 and 2 or 1,s.w==7 and 5 or 2)end;for _,q in ipairs(parts)do box(q.x,q.y,1,1,q.life>9 and 2 or 5)end;box(0,0,192,12,3);color(2);g.print(w.." "..((not cfg.ammo or p.ammo<0)and"INF"or p.ammo).." KO:"..score,2,1);color(5);g.print("SET",164,1)end
g.setCanvas();g.clear(.035,.045,.055,1);g.setColor(1,1,1);g.draw(canvas,ox+(cfg.shake and sh>0 and(sh%3-1)*scale or 0),oy,0,scale,scale);if touchMode and mode=="arena"then g.setFont(uiFont);for i,b in ipairs(buttons)do local x,y,w,h=uiButton(i);g.setColor(.19,.24,.28);g.rectangle("fill",x,y,w,h,6);g.setColor(.9,.93,.92);g.printf(b[1],x,y+(h-uiFont:getHeight())/2,w,"center")end end end
function love.touchpressed(id,x,y)if mode=="arena"then local a=touchAction(x,y);if a then touches[id]=a;return end end;tap(x,y)end
function love.touchmoved(id,x,y)if mode=="arena" and touches[id]then touches[id]=touchAction(x,y)or touches[id]end end
function love.touchreleased(id)touches[id]=nil end
function love.mousepressed(x,y,b,istouch)if not istouch then tap(x,y)end end
function love.keypressed(k)if k=="escape"or k=="p"then mode=mode=="arena"and"settings"or"arena";prev=controls();return end;if mode=="settings"then if k=="up"then menuIndex=(menuIndex-2)%#rules+1 elseif k=="down"then menuIndex=menuIndex%#rules+1 elseif k=="left"then change(menuIndex,-1)elseif k=="right"or k=="return"then change(menuIndex,1)end else local n=tonumber(k);if n and n>=1 and n<=8 then equip(n)end end end
function love.gamepadpressed(j,b)if b=="start"then love.keypressed("p")elseif mode=="settings"then if b=="dpup"then love.keypressed("up")elseif b=="dpdown"then love.keypressed("down")elseif b=="dpleft"then love.keypressed("left")elseif b=="dpright"or b=="a"then love.keypressed("right")elseif b=="b"then love.keypressed("p")end end end
